    providerRequest.provisioning = {
      ...providerRequest.provisioning,
      timeout: durationFromMs(timeout),
    };
  }
  const result = await awaitWithSignal(
    () =>
      create.call(
        this.#backend,
        providerRequest,
        operationOptions(
