} from "./client.js";
import {
  EgressMode,
  type CreateOptionsInput,
  type NetworkConfigInput,
  type SandboxSourceInput,
} from "./sandbox_data_contracts.js";

type Extends<A, B> = A extends B ? true : false;
type AssertFalse<T extends false> = T;
type AssertTrue<T extends true> = T;

const okNetwork = {
  egress: EgressMode.Restricted,
  outboundCidrs: ["192.0.2.0/24"],
  outboundDomains: ["example.com"],
  inboundCidrs: [],
  privateNetwork: true,
} satisfies NetworkConfigInput;

const okSource = { providerDefault: true } satisfies SandboxSourceInput;
const okImage = { image: { reference: "alpine:3.21" } } satisfies SandboxSourceInput;

const okCreate = {
  source: okSource,
  network: okNetwork,
  environment: { A: "1" },
  labels: { k: "v" },
  providerOptions: { flag: true },
  provisioning: { timeout: 1_000 },
} satisfies CreateOptionsInput;

const okConfig = {
  auth: { apiKey: { key: "k" } },
  timeout: 30_000,
} satisfies ConfigInput;

type _cidrOk = AssertTrue<
  Extends<string[], NonNullable<NetworkConfigInput["outboundCidrs"]>>
>;
type _oldCidrRejected = AssertFalse<
  Extends<{ entries: string[] }, NonNullable<NetworkConfigInput["outboundCidrs"]>>
>;
type _pdIsTrue = AssertTrue<
  Extends<NonNullable<SandboxSourceInput["providerDefault"]>, true>
>;
type _pdNotEmptyObj = AssertFalse<
  Extends<{}, NonNullable<SandboxSourceInput["providerDefault"]>>
>;
type _envIsRecord = AssertTrue<
  Extends<NonNullable<CreateOptionsInput["environment"]>, Record<string, string>>
>;
type _timeoutIsNumber = AssertTrue<
  Extends<NonNullable<ConfigInput["timeout"]>, number>
>;

void okImage;

const wire = materializeCreateOptions(okCreate);
if (wire.source?.kind?.case !== "providerDefault") throw new Error("source");
if (wire.network?.outboundCidrs?.entries[0] !== "192.0.2.0/24")
  throw new Error("cidr");
if (wire.network?.inboundCidrs?.entries.length !== 0) throw new Error("empty inbound");
if (wire.environment?.A !== "1" || wire.labels?.k !== "v") throw new Error("maps");

const cfg = materializeClientConfig(okConfig);
if (durationMs(cfg.timeout!) !== 30_000) throw new Error("timeout");
if (cfg.auth?.credentials?.case !== "apiKey") throw new Error("auth");

console.log("type+runtime checks ok");
